/** Lifecycle states for an outbound delivery. */
export const DeliveryState = {
  Queued: "queued",
  Sending: "sending",
  Delivered: "delivered",
  Failed: "failed"
} as const

/** Lifecycle states for an outbound delivery. */
export type DeliveryState = (typeof DeliveryState)[keyof typeof DeliveryState]

const transitions: Readonly<Record<DeliveryState, ReadonlyArray<DeliveryState>>> = {
  queued: [DeliveryState.Sending],
  sending: [DeliveryState.Delivered, DeliveryState.Failed],
  delivered: [],
  failed: [DeliveryState.Queued]
}

export const canTransition = (
  current: DeliveryState,
  next: DeliveryState
): boolean => transitions[current].includes(next)

export const isTerminal = (state: DeliveryState): boolean =>
  state === DeliveryState.Delivered

export const parseDeliveryState = (input: string): DeliveryState | undefined => {
  switch (input) {
    case DeliveryState.Queued:
    case DeliveryState.Sending:
    case DeliveryState.Delivered:
